def target_dates(day_mode):
    now = california_now()
    today = now.strftime("%Y-%m-%d")
    tomorrow = (now + timedelta(days=1)).strftime("%Y-%m-%d")
    if day_mode == "Today":
        return [today]
    if day_mode == "Tomorrow":
        return [tomorrow]
    return [today, tomorrow]

@st.cache_data(ttl=300, show_spinner=False)
def get_schedule(date_str):
    return safe_get_json(
        f"{MLB_BASE}/schedule",
        params={"sportId": 1, "date": date_str, "hydrate": "probablePitcher,venue,team"}
    ) or {"dates": []}

def extract_probable_pitchers(date_str):
    sched = get_schedule(date_str)
    rows = []
    for d in sched.get("dates", []):
        for g in d.get("games", []):
            game_pk = g.get("gamePk")
            teams = g.get("teams", {})
            away = teams.get("away", {}).get("team", {})
            home = teams.get("home", {}).get("team", {})
            away_pp = teams.get("away", {}).get("probablePitcher")
            home_pp = teams.get("home", {}).get("probablePitcher")
            status = g.get("status", {}).get("abstractGameState", "Preview")
            game_time = g.get("gameDate", "")
            venue = g.get("venue", {}).get("name", "")

            if away_pp:
                rows.append({
                    "date": date_str,
                    "game_pk": game_pk,
                    "game_time": game_time,
                    "status": status,
                    "venue": venue,
                    "pitcher_id": away_pp.get("id"),
                    "pitcher": away_pp.get("fullName"),
                    "hand": away_pp.get("pitchHand", {}).get("code", "R"),
                    "team": away.get("abbreviation", away.get("name")),
                    "team_id": away.get("id"),
                    "opponent": home.get("abbreviation", home.get("name")),
                    "opp_team_id": home.get("id"),
                    "home_team": home.get("name"),
                    "away_team": away.get("name"),
                    "opp_side": "home",
                    "matchup": f"{away.get('abbreviation', away.get('name'))} @ {home.get('abbreviation', home.get('name'))}",
                    "pitcher_confirmed": True
                })
            if home_pp:
                rows.append({
                    "date": date_str,
                    "game_pk": game_pk,
                    "game_time": game_time,
                    "status": status,
                    "venue": venue,
                    "pitcher_id": home_pp.get("id"),
                    "pitcher": home_pp.get("fullName"),
                    "hand": home_pp.get("pitchHand", {}).get("code", "R"),
                    "team": home.get("abbreviation", home.get("name")),
                    "team_id": home.get("id"),
                    "opponent": away.get("abbreviation", away.get("name")),
                    "opp_team_id": away.get("id"),
                    "home_team": home.get("name"),
                    "away_team": away.get("name"),
                    "opp_side": "away",
                    "matchup": f"{away.get('abbreviation', away.get('name'))} @ {home.get('abbreviation', home.get('name'))}",
                    "pitcher_confirmed": True
                })
    for _p in locals().get("board", locals().get("rows", locals().get("out", []))):
        if isinstance(_p, dict) and "prop_rows" in _p:
            _p["prop_rows"] = clean_real_prop_debug_rows(_p.get("prop_rows", []))
    return rows

def get_pitcher_profile(pid):
    data = safe_get_json(
        f"{MLB_BASE}/people/{pid}/stats",
        params={"stats": "season", "group": "pitching"}
    )
    default = {"Pitcher K%": LEAGUE_AVG_K, "BF": 0, "SO": 0, "BB": None, "HR": None, "H": None, "R": None, "ER": None, "HBP": None, "IP": None, "AVG IP": None, "K/9": None, "H/9": None, "BB/9": None, "ERA": None, "WHIP": None, "BAA": None, "BB%": None, "K-BB%": None, "BABIP": None, "FIP": None, "xFIP": None, "SIERA": None, "source": "Fallback league avg"}
    try:
        split = get_first_stat_split(data)
        if not split:
            return default
        stat = split.get("stat", {})
        ip = baseball_ip_to_float(stat.get("inningsPitched"))
        so = safe_float(stat.get("strikeOuts"), 0) or 0
        bb = safe_float(stat.get("baseOnBalls"), 0) or 0
        hr = safe_float(stat.get("homeRuns"), 0) or 0
        hits_allowed = safe_float(stat.get("hits"), 0) or 0
        runs_allowed = safe_float(stat.get("runs"), 0) or 0
        earned_runs = safe_float(stat.get("earnedRuns"), 0) or 0
        hbp_allowed = safe_float(stat.get("hitByPitch"), 0) or 0
        at_bats_against = safe_float(stat.get("atBats"), 0) or 0
        bf = safe_float(stat.get("battersFaced"), 0) or 0
        gs = safe_float(stat.get("gamesStarted"), None)
        gp = safe_float(stat.get("gamesPlayed"), 0) or 0
        starts = gs if gs and gs > 0 else gp
        k_pct = so / bf if bf > 0 else LEAGUE_AVG_K
        bb_pct = bb / bf if bf > 0 else None
        kbb_pct = (k_pct - bb_pct) if bb_pct is not None else None
        k9 = so / ip * 9 if ip and ip > 0 else None
        h9 = hits_allowed / ip * 9 if ip and ip > 0 else None
        bb9 = bb / ip * 9 if ip and ip > 0 else None
        era = safe_float(stat.get("era"), None)
        if era is None and ip and ip > 0:
            era = earned_runs / ip * 9
        whip = safe_float(stat.get("whip"), None)
        if whip is None and ip and ip > 0:
            whip = (hits_allowed + bb) / ip
        baa = safe_float(stat.get("avg"), None)
        if baa is None and at_bats_against > 0:
            baa = hits_allowed / at_bats_against
        avg_ip = ip / starts if starts and starts > 0 and ip else None
        # Pitcher BABIP regression signal: DIPS-style context only. It should not drive K projection.
        balls_in_play = max(0.0, bf - so - bb - hbp_allowed - hr)
        pitcher_babip = ((hits_allowed - hr) / balls_in_play) if balls_in_play > 0 else None
        shrunk = ((k_pct * bf) + (LEAGUE_AVG_K * 150)) / max(bf + 150, 1)
        dips = build_dips_metrics_from_counts(so=so, bb=bb, hr=hr, ip=ip, bf=bf)
        return {
            "Pitcher K%": float(clamp(shrunk, 0.08, 0.45)),
            "BF": bf, "SO": so, "BB": bb, "HR": hr, "H": hits_allowed, "R": runs_allowed, "ER": earned_runs, "HBP": hbp_allowed, "IP": ip,
            "AVG IP": avg_ip, "K/9": k9,
            "H/9": None if h9 is None else float(h9),
            "BB/9": None if bb9 is None else float(bb9),
            "ERA": None if era is None else float(era),
            "WHIP": None if whip is None else float(whip),
            "BAA": None if baa is None else float(baa),
            "BB%": None if bb_pct is None else float(bb_pct),
            "K-BB%": None if kbb_pct is None else float(kbb_pct),
            "BABIP": None if pitcher_babip is None else float(clamp(pitcher_babip, 0.180, 0.430)),
            "FIP": dips.get("fip"), "xFIP": dips.get("xfip"), "SIERA": dips.get("siera"),
            "source": "Season K/BF + DIPS with shrink"
        }
    except Exception:
        return default

def get_recent_logs(pid, n=12):
    data = safe_get_json(f"{MLB_BASE}/people/{pid}/stats", params={"stats": "gameLog", "group": "pitching"})
    rows = []
    try:
        splits = data["stats"][0]["splits"]
    except Exception:
        return rows
    for g in splits[:n]:
        stat = g.get("stat", {})
        ip_float = baseball_ip_to_float(stat.get("inningsPitched"))
        bf = safe_float(stat.get("battersFaced"))
        so = safe_float(stat.get("strikeOuts"))
        pitches = safe_float(stat.get("numberOfPitches"))
        rows.append({
            "Date": g.get("date"),
            "Opponent": g.get("opponent", {}).get("name"),
            "IP": stat.get("inningsPitched"),
            "IP_float": ip_float,
            "Ks": so,
            "BF": bf,
            "Pitches": pitches,
            "ER": safe_float(stat.get("earnedRuns")),
            "H": safe_float(stat.get("hits")),
            "R": safe_float(stat.get("runs")),
            "BB": safe_float(stat.get("baseOnBalls")),
            "K%": None if not bf else round((so or 0) / bf * 100, 1)
        })
    return rows

def build_leash_model(recent_rows):
    """Projected batters faced with a safer pitcher-leash model."""
    if not recent_rows:
        return {
            "expected_bf": DEFAULT_BF,
            "ppb": 3.9,
            "recent_ip": 5.5,
            "last_10_ks": [],
            "leash_risk": "UNKNOWN",
            "source": "Default fallback"
        }

    df = pd.DataFrame(recent_rows)

    def mean_col(col, rows=None):
        try:
            x = df[col] if rows is None else df.head(rows)[col]
            x = pd.to_numeric(x, errors="coerce").dropna()
            return float(x.mean()) if len(x) else None
        except Exception:
            return None

    avg_bf_l10 = mean_col("BF")
    avg_bf_l5 = mean_col("BF", 5)
    avg_bf_l3 = mean_col("BF", 3)
    avg_ip_l3 = mean_col("IP_float", 3)
    avg_pitches_l3 = mean_col("Pitches", 3)
    avg_pitches_l5 = mean_col("Pitches", 5)

    if avg_bf_l3 and avg_bf_l5 and avg_bf_l10:
        expected_bf = avg_bf_l3 * 0.55 + avg_bf_l5 * 0.30 + avg_bf_l10 * 0.15
        source = "Weighted L3/L5/L10 BF"
    elif avg_bf_l3 and avg_bf_l10:
        expected_bf = avg_bf_l3 * 0.65 + avg_bf_l10 * 0.35
        source = "Weighted L3/L10 BF"
    elif avg_bf_l3:
        expected_bf = avg_bf_l3
        source = "Last 3 BF"
    elif avg_bf_l10:
        expected_bf = avg_bf_l10
        source = "Last 10 BF"
    else:
        expected_bf = DEFAULT_BF
        source = "Default fallback"

    ppb = 3.9
    if avg_pitches_l3 and avg_bf_l3 and avg_bf_l3 > 0:
        ppb = avg_pitches_l3 / avg_bf_l3

    leash_risk = "NORMAL"

    # v9.7 stricter leash: volume is the biggest source of false OVER confidence.
    if ppb >= 4.25:
        expected_bf -= 2.7
        leash_risk = "HIGH_PITCH_COUNT"
    elif ppb >= 4.05:
        expected_bf -= 1.4
        leash_risk = "MILD_PITCH_COUNT"

    # Recent short starts reduce leash confidence more aggressively.
    if avg_ip_l3 is not None and avg_ip_l3 < 5.0:
        expected_bf -= 2.1
        leash_risk = "SHORT_RECENT_STARTS"

    # Recent very high pitch workload: stronger fatigue haircut.
    if avg_pitches_l5 is not None and avg_pitches_l5 > 95:
        expected_bf -= 1.4
        leash_risk = "HIGH_RECENT_WORKLOAD"

    pitch_trend_factor, pitch_trend_note = pitch_count_trend_bf_factor(recent_rows)
    expected_bf = float(clamp(expected_bf * pitch_trend_factor, 14, 31))

    return {
        "expected_bf": expected_bf,
        "ppb": float(ppb),
        "recent_ip": float(avg_ip_l3 or 5.5),
        "last_10_ks": [safe_int(r.get("Ks"), 0) or 0 for r in recent_rows[:10]],
        "leash_risk": leash_risk,
        "pitch_count_trend_factor": round(float(pitch_trend_factor), 3),
        "pitch_count_trend_note": pitch_trend_note,
        "source": f"{source}; {pitch_trend_note}"
    }

def apply_managerial_hook_v11_9(expected_bf, recent_rows):
    """v11.9: conservative starter-volume haircut for repeated early hooks.

    Uses the pitcher's recent game logs only. If he is getting pulled around or
    before the third-time-through window too often, we trim expected BF slightly.
    The cut is capped and does not remove the existing leash/pitch-count model.
    """
    bf0 = safe_float(expected_bf, DEFAULT_BF) or DEFAULT_BF
    if not recent_rows:
        return bf0, "UNKNOWN", "Manager hook neutral: no recent starts"
    usable = []
    for r in recent_rows[:8]:
        bf = safe_float(r.get("BF"), None)
        if bf is not None and bf > 0:
            usable.append(bf)
    if len(usable) < 3:
        return bf0, "LOW_SAMPLE", f"Manager hook neutral: only {len(usable)} recent BF samples"
    early_hooks = sum(1 for bf in usable if bf <= MANAGER_HOOK_RECENT_BF_CUTOFF)
    hook_rate = early_hooks / max(1, len(usable))
    if hook_rate >= MANAGER_HOOK_RATE_TRIGGER and bf0 >= TTTO_THRESHOLD_BATTERS:
        new_bf = float(clamp(bf0 * (1.0 - MANAGER_HOOK_STRICTNESS), 14, 31))
        return new_bf, "STRICT_HOOK", f"Manager hook cut x{1.0-MANAGER_HOOK_STRICTNESS:.3f}: early-hook rate {hook_rate:.0%} ({early_hooks}/{len(usable)})"
    return bf0, "NORMAL", f"Manager hook normal: early-hook rate {hook_rate:.0%} ({early_hooks}/{len(usable)})"

def blend_pitcher_k_rate(profile_k, recent_rows, pitcher_id):
    profile_k = profile_k if profile_k is not None else LEAGUE_AVG_K
    recent_rates = []
    for r in recent_rows[:5]:
        bf = safe_float(r.get("BF"))
        ks = safe_float(r.get("Ks"))
        if bf and bf > 0 and ks is not None:
            recent_rates.append(ks / bf)
    if recent_rates:
        l5 = float(np.mean(recent_rates))
        base = profile_k * 0.70 + l5 * 0.30
        source = "Season K% + recent-start K% blend"
    else:
        base = profile_k
        source = "Season pitcher K%"
    learned, scale = apply_learning(pitcher_id, base)
    return clamp(learned, 0.08, 0.48), source, scale

def calculate_log5_k_rate(pitcher_k, lineup_k, league_avg_k=LEAGUE_AVG_K):
    pitcher_k = clamp(pitcher_k, 0.01, 0.60)
    lineup_k = clamp(lineup_k, 0.01, 0.60)
    num = (pitcher_k * lineup_k) / league_avg_k
    den = num + ((1 - pitcher_k) * (1 - lineup_k)) / (1 - league_avg_k)
    return float(num / den)

# =========================
# v10.9 TRUE EDGE MERGE HELPERS
# =========================
def elite_pitcher_boost_factor(k_rate):
    """Small K-skill boost for elite strikeout arms.

    Kept conservative because Statcast, recent form, and Log5 already capture a lot
    of pitcher skill. This should never turn a weak edge into an automatic play.
    """
    k_rate = safe_float(k_rate, LEAGUE_AVG_K) or LEAGUE_AVG_K
    if k_rate >= 0.30:
        return 1.035, "Elite pitcher K boost x1.035"
    if k_rate >= 0.27:
        return 1.025, "High-K pitcher boost x1.025"
    if k_rate >= 0.24:
        return 1.015, "Above-average pitcher K boost x1.015"
    return 1.000, "No elite pitcher boost"

def opponent_k_context_factor(lineup_k):
    """Extra lineup strikeout-context nudge after Log5.

    The main opponent-K signal is still the posted-lineup/hitter blend. This small
    factor only recognizes extreme high-K or low-K lineups without double-counting.
    """
    lk = safe_float(lineup_k, LEAGUE_AVG_K) or LEAGUE_AVG_K
    diff = lk - LEAGUE_AVG_K
    if diff >= 0.040:
        return 1.045, "Extreme high-K opponent context x1.045"
    if diff >= 0.030:
        return 1.035, "High-K opponent context x1.035"
    if diff >= 0.020:
        return 1.020, "Above-average opponent K context x1.020"
    if diff <= -0.035:
        return 0.955, "Extreme contact opponent context x0.955"
    if diff <= -0.025:
        return 0.970, "Low-K opponent context x0.970"
    return 1.000, "Neutral opponent K context"

def pitch_count_trend_bf_factor(recent_rows):
    """Recent pitch-count trend factor for starter BF/leash.

    Uses only real recent game-log pitch counts. Missing data remains neutral.
    """
    vals = []
    for r in (recent_rows or [])[:3]:
        p = safe_float(r.get("Pitches"))
        if p is not None and p > 0:
            vals.append(p)
    if not vals:
        return 1.0, "Pitch-count trend unavailable; neutral"
    avg = float(np.mean(vals))
    if avg >= 100:
        return 1.040, f"Recent pitch-count leash boost x1.040 (L3 avg {avg:.0f})"
    if avg >= 92:
        return 1.020, f"Recent pitch-count leash boost x1.020 (L3 avg {avg:.0f})"
    if avg <= 82:
        return 0.940, f"Recent low pitch-count leash cut x0.940 (L3 avg {avg:.0f})"
    return 1.000, f"Neutral pitch-count trend (L3 avg {avg:.0f})"


def build_pitch_count_module(recent_rows):
    """Pitch Count 2.0: converts recent real pitch-count workload into a volume score.

    This is intentionally tied to the existing BF/leash engine. It does not create
    fake data; missing pitch counts stay neutral. The module returns a 0-100 score,
    a label, a BF adjustment, and a small volatility tax used by decision filters.
    """
    rows = list(recent_rows or [])
    pitch_vals = []
    bf_vals = []
    ip_vals = []
    for r in rows[:10]:
        pc = safe_float(r.get("Pitches"), None)
        bf = safe_float(r.get("BF"), None)
        ip = safe_float(r.get("IP_float"), None)
        if pc is not None and pc > 0:
            pitch_vals.append(float(pc))
        if bf is not None and bf > 0:
            bf_vals.append(float(bf))
        if ip is not None and ip > 0:
            ip_vals.append(float(ip))

    if not pitch_vals:
        return {
            "score": 72,
            "label": "PITCH_COUNT_UNKNOWN",
            "bf_adj": 0.0,
            "bf_factor": 1.0,
            "volatility_tax": 0.02,
            "avg_l3": None,
            "avg_l5": None,
            "avg_l10": None,
            "trend": 0.0,
            "note": "Pitch Count 2.0 neutral: no recent pitch-count data",
        }

    avg_l3 = float(np.mean(pitch_vals[:3])) if len(pitch_vals) >= 1 else None
    avg_l5 = float(np.mean(pitch_vals[:5])) if len(pitch_vals) >= 1 else avg_l3
    avg_l10 = float(np.mean(pitch_vals[:10])) if len(pitch_vals) >= 1 else avg_l5
    ip_l3 = float(np.mean(ip_vals[:3])) if ip_vals else None
    bf_l3 = float(np.mean(bf_vals[:3])) if bf_vals else None
    trend = 0.0
    if avg_l3 is not None and avg_l10 is not None:
        trend = avg_l3 - avg_l10

    score = 70.0
    # Recent pitch ceiling / leash.
    if avg_l3 >= 98:
        score += 18
    elif avg_l3 >= 92:
        score += 10
    elif avg_l3 >= 86:
        score += 3
    elif avg_l3 >= 80:
        score -= 8
    else:
        score -= 18

    # Longer-term volume support.
    if avg_l5 >= 95:
        score += 8
    elif avg_l5 >= 88:
        score += 3
    elif avg_l5 < 82:
        score -= 8

    # Innings and BF confirmation.
    if ip_l3 is not None:
        if ip_l3 >= 6.0:
            score += 7
        elif ip_l3 < 5.0:
            score -= 12
    if bf_l3 is not None:
        if bf_l3 >= 24:
            score += 5
        elif bf_l3 < 20:
            score -= 8

    # Direction of pitch-count trend.
    if trend >= 5:
        score += 5
    elif trend <= -7:
        score -= 7

    score = int(round(clamp(score, 35, 100)))

    if score >= 92:
        label = "ELITE_VOLUME"
        bf_adj, bf_factor, vol_tax = 0.70, 1.025, 0.00
    elif score >= 84:
        label = "FULL_LEASH"
        bf_adj, bf_factor, vol_tax = 0.35, 1.012, 0.00
    elif score >= 72:
        label = "NORMAL"
        bf_adj, bf_factor, vol_tax = 0.00, 1.000, 0.01
    elif score >= 60:
        label = "MONITOR"
        bf_adj, bf_factor, vol_tax = -0.55, 0.982, 0.025
    else:
        label = "SHORT_LEASH"
        bf_adj, bf_factor, vol_tax = -1.20, 0.958, 0.045

    note = f"Pitch Count 2.0 {label}: score {score}/100; L3 {avg_l3:.0f}, L5 {avg_l5:.0f}, trend {trend:+.1f}; BF adj {bf_adj:+.2f}"
    return {
        "score": score,
        "label": label,
        "bf_adj": round(float(bf_adj), 2),
        "bf_factor": round(float(bf_factor), 3),
        "volatility_tax": round(float(vol_tax), 3),
        "avg_l3": round(float(avg_l3), 1) if avg_l3 is not None else None,
        "avg_l5": round(float(avg_l5), 1) if avg_l5 is not None else None,
        "avg_l10": round(float(avg_l10), 1) if avg_l10 is not None else None,
        "trend": round(float(trend), 1),
        "note": note,
    }



def v3_role_stability_from_ip(ip_vals, pitch_count_profile=None, manager_hook_status=None):
    """V3 IP-test helper. Uses recent real IP + role/leash labels to create a small stability score.
    This is used only inside the V3 test file and is capped before affecting projected IP.
    """
    vals = [float(x) for x in (ip_vals or []) if x is not None]
    l5 = vals[:5]
    score = 50
    notes = []
    if not l5:
        score -= 12; notes.append("no recent IP")
    else:
        starter_like = sum(1 for x in l5 if x >= 4.0)
        deep = sum(1 for x in l5 if x >= 5.0)
        avg = sum(l5) / len(l5)
        if starter_like >= 4:
            score += 18; notes.append("starter workload")
        elif starter_like <= 2:
            score -= 18; notes.append("short/swing workload")
        if deep >= 3:
            score += 8; notes.append("recent 5+ IP")
        if len(l5) >= 3 and (max(l5) - min(l5)) >= 2.5:
            score -= 14; notes.append("volatile leash")
        if avg >= 5.8:
            score += 6; notes.append("strong L5 IP")
        elif avg <= 4.2:
            score -= 8; notes.append("weak L5 IP")
    pc_label = str((pitch_count_profile or {}).get("label") or "").upper()
    hook = str(manager_hook_status or "").upper()
    if pc_label in ["FULL_LEASH", "ELITE_VOLUME"]:
        score += 8; notes.append(f"pitch count {pc_label}")
    elif pc_label in ["SHORT_LEASH", "MONITOR"]:
        score -= 8; notes.append(f"pitch count {pc_label}")
    if hook == "STRICT_HOOK":
        score -= 10; notes.append("strict manager hook")
    score = int(clamp(score, 0, 100))
    label = "STABLE_STARTER" if score >= 78 else "MOSTLY_STABLE" if score >= 63 else "ROLE_WATCH" if score >= 48 else "HIGH_ROLE_RISK"
    return score, label, "; ".join(notes[:5]) if notes else "normal role profile"



def v3_team_leash_score_profile(recent_ip_vals=None, pitch_count_profile=None, manager_hook_status=None, bullpen_usage=None):
    """V3 IP+ helper: estimates how likely the pitcher/team is to allow starter length.

    This is a small innings-context model only. It does not touch pitcher K skill.
    Uses real recent IP, recent pitch-count label, manager hook label, and bullpen workload.
    """
    vals = [float(x) for x in (recent_ip_vals or []) if x is not None]
    l5 = vals[:5]
    score = 50.0
    reasons = []

    if l5:
        avg_l3 = sum(l5[:3]) / max(1, len(l5[:3]))
        avg_l5 = sum(l5) / len(l5)
        deep5 = sum(1 for x in l5 if x >= 5.0)
        deep6 = sum(1 for x in l5 if x >= 6.0)
        short4 = sum(1 for x in l5 if x < 4.0)
        if avg_l5 >= 5.8:
            score += 16; reasons.append(f"L5 IP avg {avg_l5:.1f}")
        elif avg_l5 >= 5.2:
            score += 8; reasons.append(f"L5 IP solid {avg_l5:.1f}")
        elif avg_l5 <= 4.2:
            score -= 14; reasons.append(f"L5 IP low {avg_l5:.1f}")
        if avg_l3 >= avg_l5 + 0.45:
            score += 7; reasons.append("L3 leash rising")
        elif avg_l3 <= avg_l5 - 0.45:
            score -= 7; reasons.append("L3 leash falling")
        if deep6 >= 2:
            score += 7; reasons.append("multiple 6+ IP starts")
        if deep5 >= 4:
            score += 5; reasons.append("regular 5+ IP")
        if short4 >= 2:
            score -= 12; reasons.append("multiple short starts")
    else:
        score -= 8; reasons.append("no recent IP sample")

    pc_label = str((pitch_count_profile or {}).get("label") or "").upper()
    pc_avg_l3 = safe_float((pitch_count_profile or {}).get("avg_l3"), None)
    if pc_label in ["ELITE_VOLUME", "FULL_LEASH"] or (pc_avg_l3 is not None and pc_avg_l3 >= 96):
        score += 10; reasons.append("pitch count supports leash")
    elif pc_label in ["SHORT_LEASH", "MONITOR"] or (pc_avg_l3 is not None and pc_avg_l3 <= 82):
        score -= 10; reasons.append("pitch count limits leash")

    hook = str(manager_hook_status or "").upper()
    if hook == "STRICT_HOOK":
        score -= 12; reasons.append("strict manager hook")
    elif hook == "NORMAL":
        score += 3

    if isinstance(bullpen_usage, dict):
        bp_label = str(bullpen_usage.get("label") or "").upper()
        bp_pitches = safe_float(bullpen_usage.get("bullpen_pitches"), 0) or 0
        bp_ip = safe_float(bullpen_usage.get("bullpen_ip"), 0) or 0
        if bp_label in ["TIRED", "VERY_TIRED", "HEAVY"] or bp_pitches >= 200 or bp_ip >= 14:
            score += 8; reasons.append("bullpen workload may extend starter")
        elif bp_label in ["FRESH"] or (bp_pitches <= 100 and bp_ip <= 7):
            score -= 4; reasons.append("fresh bullpen quick-hook risk")

    score = int(clamp(score, 0, 100))
    label = "DEEP_LEASH" if score >= 78 else "NORMAL_LEASH" if score >= 60 else "LEASH_WATCH" if score >= 45 else "SHORT_LEASH_RISK"
    return {"score": score, "label": label, "note": "; ".join(reasons[:6]) if reasons else "neutral leash profile"}

def v3_ip_accuracy_adjustment(projected_ip, ip_from_bf, recent_l3_ip, recent_l5_ip, recent_l10_ip, pitch_count_profile=None, manager_hook_status=None, game_script_risk=None, recent_ip_vals=None, bullpen_usage=None):
    """Small V3 test nudge to get innings closer without letting IP swing wildly.
    Max move is V3_IP_ACCURACY_MAX_ADJ, default 0.60 innings in IP+ test.
    """
    if not globals().get("V3_IP_ACCURACY_TEST_ENABLED", True):
        return float(projected_ip), 0.0, "IP test OFF", 50, "OFF"
    base = safe_float(projected_ip, None)
    if base is None:
        return projected_ip, 0.0, "No base IP", 50, "UNKNOWN"
    adj = 0.0
    notes = []
    vals = []
    for v in [recent_l3_ip, recent_l5_ip, recent_l10_ip]:
        n = safe_float(v, None)
        if n is not None:
            vals.append(n)
    role_score, role_label, role_note = v3_role_stability_from_ip((recent_ip_vals or vals), pitch_count_profile=pitch_count_profile, manager_hook_status=manager_hook_status)
    team_leash = v3_team_leash_score_profile(recent_ip_vals=(recent_ip_vals or vals), pitch_count_profile=pitch_count_profile, manager_hook_status=manager_hook_status, bullpen_usage=bullpen_usage)
    if recent_l5_ip is not None:
        diff = float(recent_l5_ip) - float(base)
        if diff >= 0.85:
            adj += 0.24; notes.append("recent IP above projection")
        elif diff <= -0.85:
            adj -= 0.24; notes.append("recent IP below projection")
        if recent_l3_ip is not None:
            l3diff = float(recent_l3_ip) - float(recent_l5_ip)
            if l3diff >= 0.55:
                adj += 0.12; notes.append("L3 leash rising")
            elif l3diff <= -0.55:
                adj -= 0.12; notes.append("L3 leash falling")
        if recent_l10_ip is not None:
            l5_l10_diff = float(recent_l5_ip) - float(recent_l10_ip)
            if l5_l10_diff >= 0.45:
                adj += 0.08; notes.append("L5 above L10")
            elif l5_l10_diff <= -0.45:
                adj -= 0.08; notes.append("L5 below L10")
    pc_label = str((pitch_count_profile or {}).get("label") or "").upper()
    if pc_label in ["ELITE_VOLUME", "FULL_LEASH"]:
        adj += 0.10; notes.append(f"{pc_label} support")
    elif pc_label in ["SHORT_LEASH", "MONITOR"]:
        adj -= 0.12; notes.append(f"{pc_label} tax")
    hook = str(manager_hook_status or "").upper()
    if hook == "STRICT_HOOK":
        adj -= 0.15; notes.append("strict hook tax")
    gs_label = str((game_script_risk or {}).get("label") or "").upper() if isinstance(game_script_risk, dict) else ""
    if gs_label in ["HIGH", "EXTREME"]:
        adj -= 0.10; notes.append("game-script pull risk")
    tl_score = safe_float((team_leash or {}).get("score"), 50) or 50
    tl_label = str((team_leash or {}).get("label") or "")
    if tl_score >= 78:
        adj += 0.12; notes.append(f"team leash {tl_label}")
    elif tl_score < 45:
        adj -= 0.12; notes.append(f"team leash {tl_label}")
    elif tl_score >= 60:
        adj += 0.04; notes.append(f"team leash {tl_label}")
    # role score acts as a tiny guardrail, not a full projection engine.
    if role_score >= 78:
        adj += 0.08
    elif role_score < 48:
        adj -= 0.12
    cap = safe_float(globals().get("V3_IP_ACCURACY_MAX_ADJ", 0.45), 0.45) or 0.45
    adj = float(clamp(adj, -cap, cap))
    new_ip = float(clamp(base + adj, 2.4, 8.1))
    leash_label = (team_leash or {}).get("label", "—")
    leash_score = (team_leash or {}).get("score", "—")
    note = f"V3 IP+ test {adj:+.2f}: " + ("; ".join(notes[:6]) if notes else "neutral") + f" | role {role_label} {role_score}/100 | leash {leash_label} {leash_score}/100"
    return new_ip, round(adj, 2), note, role_score, role_label

def build_innings_outcome_module(recent_rows, expected_bf, ppb=None, pitch_count_profile=None, manager_hook_status=None, game_script_risk=None, bullpen_usage=None):
    """Project starter innings outcome and early-pull risk from real recent IP/BF/pitch-count data."""
    rows = list(recent_rows or [])
    ip_vals, bf_vals, bf_per_ip_vals = [], [], []
    for r in rows[:10]:
        ip = safe_float(r.get("IP_float"), None)
        bf0 = safe_float(r.get("BF"), None)
        if ip is not None and ip > 0:
            ip_vals.append(float(ip))
        if bf0 is not None and bf0 > 0:
            bf_vals.append(float(bf0))
        if ip is not None and ip > 0 and bf0 is not None and bf0 > 0:
            bf_per_ip_vals.append(float(bf0) / float(ip))
    exp_bf = safe_float(expected_bf, DEFAULT_BF) or DEFAULT_BF
    bf_per_ip = float(clamp(np.mean(bf_per_ip_vals), 3.65, 5.15)) if bf_per_ip_vals else 4.25
    ip_from_bf = exp_bf / bf_per_ip
    recent_l3_ip = float(np.mean(ip_vals[:3])) if ip_vals else None
    recent_l5_ip = float(np.mean(ip_vals[:5])) if ip_vals else recent_l3_ip
    recent_l10_ip = float(np.mean(ip_vals[:10])) if ip_vals else recent_l5_ip
    # V3 IP+: more recent usage weighted, while BF model remains the anchor.
    if recent_l5_ip is not None and recent_l10_ip is not None:
        projected_ip = (ip_from_bf * 0.45) + (recent_l5_ip * 0.40) + (recent_l10_ip * 0.15)
    elif recent_l5_ip is not None:
        projected_ip = (ip_from_bf * 0.55) + (recent_l5_ip * 0.45)
    else:
        projected_ip = ip_from_bf
    pc_label = str((pitch_count_profile or {}).get("label") or "").upper()
    hook = str(manager_hook_status or "").upper()
    gs_label = str((game_script_risk or {}).get("label") or "").upper() if isinstance(game_script_risk, dict) else ""
    risk_points, reasons = 0, []
    if recent_l3_ip is not None and recent_l3_ip < 5.0:
        risk_points += 22; reasons.append("L3 IP below 5.0")
    elif recent_l3_ip is not None and recent_l3_ip >= 6.0:
        risk_points -= 8; reasons.append("L3 IP supports 6+ innings")
    if exp_bf < 20:
        risk_points += 18; reasons.append("expected BF under 20")
    elif exp_bf >= 24:
        risk_points -= 8; reasons.append("expected BF supports normal leash")
    if pc_label in ["SHORT_LEASH", "MONITOR"]:
        risk_points += 18; reasons.append(f"pitch count {pc_label}")
    elif pc_label in ["FULL_LEASH", "ELITE_VOLUME"]:
        risk_points -= 8; reasons.append(f"pitch count {pc_label}")
    if hook == "STRICT_HOOK":
        risk_points += 20; reasons.append("manager hook strict")
    if gs_label in ["HIGH", "EXTREME"]:
        risk_points += 12; reasons.append(f"game script {gs_label}")
    # V3 test: small capped IP nudge from recent IP trend + role stability + leash context.
    try:
        projected_ip, v3_ip_adj, v3_ip_note, v3_role_score, v3_role_label = v3_ip_accuracy_adjustment(
            projected_ip, ip_from_bf, recent_l3_ip, recent_l5_ip, recent_l10_ip,
            pitch_count_profile=pitch_count_profile,
            manager_hook_status=manager_hook_status,
            game_script_risk=game_script_risk,
            recent_ip_vals=ip_vals,
            bullpen_usage=bullpen_usage,
        )
    except Exception as _v3ip_e:
        v3_ip_adj, v3_ip_note, v3_role_score, v3_role_label = 0.0, f"V3 IP test skipped: {_v3ip_e}", 50, "UNKNOWN"
    risk_score = int(clamp(50 + risk_points, 5, 95))
    if risk_score >= 78:
        label = "EARLY_PULL_HIGH"
    elif risk_score >= 62:
        label = "EARLY_PULL_MONITOR"
    elif risk_score <= 35:
        label = "FULL_INNINGS_PROFILE"
    else:
        label = "NORMAL_INNINGS"
    projected_ip = float(clamp(projected_ip, 2.4, 8.1))
    low_ip = float(clamp(projected_ip - (0.75 if risk_score < 62 else 1.05), 2.0, 8.0))
    high_ip = float(clamp(projected_ip + (0.70 if risk_score < 62 else 0.45), 2.0, 8.2))
    projected_pitches = None
    if ppb is not None:
        projected_pitches = float(clamp(exp_bf * (safe_float(ppb, 3.9) or 3.9), 45, 115))
    note_bits = reasons[:4] if reasons else ["normal innings/leash profile"]
    return {
        "projected_ip": round(projected_ip, 2),
        "ip_floor": round(low_ip, 2),
        "ip_ceiling": round(high_ip, 2),
        "recent_ip_l3": round(float(recent_l3_ip), 2) if recent_l3_ip is not None else None,
        "recent_ip_l5": round(float(recent_l5_ip), 2) if recent_l5_ip is not None else None,
        "recent_ip_l10": round(float(recent_l10_ip), 2) if recent_l10_ip is not None else None,
        "bf_per_ip": round(float(bf_per_ip), 2),
        "projected_pitches": round(projected_pitches, 0) if projected_pitches is not None else None,
        "early_pull_risk_score": risk_score,
        "early_pull_label": label,
        "v3_ip_test_adjustment": v3_ip_adj if 'v3_ip_adj' in locals() else 0.0,
        "v3_ip_test_note": v3_ip_note if 'v3_ip_note' in locals() else "V3 IP test unavailable",
        "v3_role_stability_score": v3_role_score if 'v3_role_score' in locals() else 50,
        "v3_role_stability_label": v3_role_label if 'v3_role_label' in locals() else "UNKNOWN",
        "v3_team_leash_score": (team_leash or {}).get("score") if 'team_leash' in locals() else None,
        "v3_team_leash_label": (team_leash or {}).get("label") if 'team_leash' in locals() else None,
        "v3_team_leash_note": (team_leash or {}).get("note") if 'team_leash' in locals() else None,
        "note": f"Innings outcome {label}: IP {projected_ip:.1f} range {low_ip:.1f}-{high_ip:.1f}; " + "; ".join(note_bits) + (" | " + (v3_ip_note if 'v3_ip_note' in locals() else "")),
    }

def tto_decay_factor(pa_index):
    """Third-time-through-order decay for PA-by-PA K probabilities."""
    i = int(pa_index)
    if i < 18:
        return 1.000
    if i < 27:
        return 0.925
    return 0.860

