    title_f = font(36, True)
    label_f = font(20, True)
    small_f = font(18, False)
    tiny_f = font(15, False)
    name_f = font(34, True)
    big_f = font(52, True)
    stat_f = font(22, True)
    white = "#f8f8ff"
    muted = "#8992a8"
    purple = "#d827ff"
    gold = "#f6c43c"
    green = "#31f08a"
    cyan = "#42d8ff"
    red = "#ff3f68"
    panel = "#0b101a"
    panel2 = "#111827"

    now_txt = california_now().strftime("%m/%d %I:%M %p PT") if "california_now" in globals() else datetime.now().strftime("%m/%d %I:%M %p")
