    draw.text((w - 260, 48), now_txt, fill=muted, font=small_f)
    draw.text((w - 260, 78), "MOBILE CARD SHEET", fill=purple, font=tiny_f)

    def pct_num(v):
        n = _v3_safe_num(v, None)
        return n if n is not None else 0

    y = top_h
