        footer_bits.append("pitcher confirmed" if confirmed_good else "probable pitcher not confirmed")
        if is_fs:
            p20 = first_num(row, ["P20", "Floor"], None)
            p80 = first_num(row, ["P80", "Ceiling"], None)
