# =========================
# FINAL UNDERDOG BATTER LINE PARSER OVERRIDE
# Keeps the V3 UI/base intact while using the newer relationship-aware line logic
# from the previous batter-only file for H+R+RBI and Home Runs.
# =========================
OW_FINAL_UD_BATTER_LINE_PARSER_VERSION = "OW_FINAL_UD_BATTER_LINES_V7_HRR_HR_2026_07_21"
OW_FINAL_UD_BATTER_ENDPOINT_SCAN_LIMIT = 3


def _ow_ud_attrs(obj):
    if not isinstance(obj, dict):
        return {}
    out = {}
    attrs = obj.get("attributes")
    if isinstance(attrs, dict):
        out.update(attrs)
    for key, value in obj.items():
        if key not in {"attributes", "relationships", "included", "data"} and key not in out:
            out[key] = value
    return out


def _ow_ud_collect(payload):
    found = []

    def walk(value, parent_key=""):
        if isinstance(value, dict):
            item = dict(value)
            if parent_key and "_parent_key" not in item:
                item["_parent_key"] = parent_key
            if any(k in item for k in ("type", "attributes", "relationships", "stat_value", "line", "title")):
                found.append(item)
            for k, child in value.items():
                if isinstance(child, (dict, list)):
                    walk(child, k)
        elif isinstance(value, list):
            for child in value:
                walk(child, parent_key)

    walk(payload)
    return found


def _ow_ud_type(obj):
    if not isinstance(obj, dict):
        return ""
    return str(obj.get("type") or obj.get("_parent_key") or "").lower().replace("-", "_")


def _ow_ud_object_maps(objects):
    by_key, by_id = {}, {}
    for obj in objects:
        oid = str(obj.get("id") or _ow_ud_attrs(obj).get("id") or "")
        if not oid:
            continue
        typ = _ow_ud_type(obj)
        for cand in {typ, typ.rstrip("s"), typ + "s"}:
            by_key[(cand, oid)] = obj
        by_id.setdefault(oid, []).append(obj)
    return by_key, by_id


def _ow_ud_related(obj, names, by_key, by_id):
    if not isinstance(obj, dict):
        return None
    rels = obj.get("relationships")
    if not isinstance(rels, dict):
        return None
    normalized = {str(k).lower().replace("-", "_"): v for k, v in rels.items()}
    for name in names:
        rel_names = {
            name.lower().replace("-", "_"),
            name.lower().replace("_", "-"),
            name.lower().replace("_", ""),
            name.lower().rstrip("s"),
            name.lower() + "s",
        }
        for rel_name in rel_names:
            rel = normalized.get(rel_name.replace("-", "_"))
            if not isinstance(rel, dict):
                continue
            data = rel.get("data")
            items = data if isinstance(data, list) else [data]
            for item in items:
                if not isinstance(item, dict):
                    continue
                oid = str(item.get("id") or "")
                typ = str(item.get("type") or rel_name or "").lower().replace("-", "_")
                if not oid:
                    continue
                for cand_t in (typ, typ.rstrip("s"), typ + "s", rel_name, rel_name.rstrip("s"), rel_name + "s"):
                    hit = by_key.get((cand_t.replace("-", "_"), oid))
                    if hit is not None:
                        return hit
                candidates = by_id.get(oid) or []
                if candidates:
                    for candidate in candidates:
                        ctyp = _ow_ud_type(candidate)
                        if rel_name.rstrip("s").replace("-", "_") in ctyp or ctyp.rstrip("s") in rel_name.replace("-", "_"):
                            return candidate
                    return candidates[0]
    return None


def _ow_ud_blob(*objects):
    keys = (
        "title", "display_title", "name", "display_name", "full_name", "first_name", "last_name",
        "player_name", "appearance_name", "short_name", "abbr_name", "stat", "stat_type",
        "appearance_stat", "appearance_stat_type", "market", "market_name", "market_display_name",
        "stat_name", "display_stat", "display_stat_name", "stat_type_name", "over_under_title",
        "label", "description", "sport", "sport_name", "league", "league_name", "status", "state",
        "active", "hidden",
    )
    parts = []
    for obj in objects:
        if not isinstance(obj, dict):
            continue
        for source in (_ow_ud_attrs(obj), obj):
            if not isinstance(source, dict):
                continue
            for key in keys:
                value = source.get(key)
                if value not in (None, "") and not isinstance(value, (dict, list)):
                    parts.append(str(value))
    return " | ".join(parts)


def _ow_ud_market(blob):
    low = str(blob or "").lower()
    if any(x in low for x in (
        "pitcher", "strikeout", "pitching outs", "hits allowed", "earned runs", "moneyline",
        "run line", "team total", "soccer", "basketball", "football", "hockey", "golf",
        "tennis", "esports", "cs2", "league of legends",
    )):
        return None
    compact = re.sub(r"[^a-z0-9]+", "", low)
    hrr_terms = (
        "hits + runs + rbis", "hits+runs+rbis", "hits runs rbis", "hits runs and rbis",
        "hits, runs, and rbis", "hits + runs + rbi", "hits+runs+rbi", "batter hits + runs + rbis",
        "h+r+rbi", "h + r + rbi", "h+r+r", "h + r + r",
    )
    hr_terms = ("home runs", "home run", "home run o/u", "home runs o/u", "batter home runs", "batter home run", "homeruns")
    if any(term in low for term in hrr_terms) or any(token in compact for token in ("hitsrunsrbis", "hitsrunsrbi", "hrrbi", "hrr")):
        return "HRR"
    if any(term in low for term in hr_terms) or any(token in compact for token in ("homeruns", "homerun", "batterhomeruns", "batterhomerun")):
        return "HR"
    return None


def _ow_ud_market_label(market):
    return {
        "HRR": "H+R+RBI",
        "HR": "Home Runs",
    }.get(str(market or "").upper(), str(market or "Batter"))


def _ow_ud_market_line_ok(market, line):
    line = _v3_safe_num(line, None)
    if line is None:
        return False
    market = str(market or "").upper()
    ranges = {
        "HR": (0.5, 2.5),
        "HRR": (0.5, 6.5),
    }
    if market not in ranges:
        return False
    lo, hi = ranges[market]
    return lo <= float(line) <= hi


def _ow_ud_line_value(*objects):
    keys = (
        "stat_value", "statValue", "line", "over_under_line", "overUnderLine",
        "over_under_value", "overUnderValue", "target_value", "targetValue",
        "line_score", "lineScore", "display_stat_value", "displayStatValue", "value", "points",
    )
    for obj in objects:
        if not isinstance(obj, dict):
            continue
        for source in (_ow_ud_attrs(obj), obj):
            if not isinstance(source, dict):
                continue
            for key in keys:
                value = safe_float(source.get(key), None)
                if value is not None and 0.5 <= value <= 8.5 and abs(value * 2 - round(value * 2)) < 1e-7:
                    return float(value)
    return None


def _ow_clean_ud_player(value):
    text = str(value or "").strip()
    patterns = [
        r"\s+Hits\s*\+\s*Runs\s*\+\s*RBIs?.*$",
        r"\s+H\s*\+\s*R\s*\+\s*R(?:BI)?.*$",
        r"\s+(?:Batter\s+)?Home\s+Runs?.*$",
        r"\s+(?:Batter\s+)?Total\s+Bases.*$",
        r"\s+(?:Batter\s+)?Runs\s+Batted\s+In.*$",
        r"\s+(?:Batter\s+)?RBIs?.*$",
        r"\s+(?:Batter\s+)?Runs.*$",
        r"\s+(?:Batter\s+)?Hits.*$",
        r"\s+Over/Under.*$",
        r"\s+O/U.*$",
        r"\s+(?:Higher|Lower|Over|Under).*$",
    ]
    for pattern in patterns:
        text = re.sub(pattern, "", text, flags=re.I).strip()
    if "_bp_clean_player_name" in globals():
        try:
            text = _bp_clean_player_name(text)
        except Exception:
            pass
    return text.strip(" -|•:")


def _ow_ud_player_name(*objects):
    values = []
    for obj in objects:
        if not isinstance(obj, dict):
            continue
        attrs = _ow_ud_attrs(obj)
        first = str(attrs.get("first_name", "")).strip()
        last = str(attrs.get("last_name", "")).strip()
        if first and last:
            values.append(f"{first} {last}")
        for key in ("player_name", "full_name", "display_name", "name", "appearance_name", "title", "short_name", "abbr_name"):
            value = attrs.get(key)
            if isinstance(value, str) and 2 <= len(value) <= 120:
                values.append(value)
    cleaned = [_ow_clean_ud_player(v) for v in values]
    cleaned = [v for v in cleaned if len(_v3_norm_name(v).split()) >= 2 and len(v) <= 65]
    if not cleaned:
        return ""
    return sorted(set(cleaned), key=lambda x: (len(_v3_norm_name(x).split()), len(x)), reverse=True)[0]


def _ow_ud_active(*objects):
    blob = _ow_ud_blob(*objects).lower()
    return not any(term in blob for term in ("suspended", "inactive", "closed", "disabled", "hidden true", "removed"))


@st.cache_data(ttl=120, show_spinner=False)
def _ow_fetch_ud_batter_hrr_hr_lines():
    rows, debug = [], {
        "parser_version": OW_FINAL_UD_BATTER_LINE_PARSER_VERSION,
        "endpoint": None,
        "status": "NO_RESPONSE",
        "objects": 0,
        "candidate_lines": 0,
        "parsed_hrr": 0,
        "parsed_hr": 0,
        "sample_market_text": [],
    }
    headers = {"Origin": "https://underdogfantasy.com", "Referer": "https://underdogfantasy.com/"}
    for idx, url in enumerate(UNDERDOG_URLS):
        if idx >= OW_FINAL_UD_BATTER_ENDPOINT_SCAN_LIMIT and rows:
            break
        payload = safe_get_json(url, timeout=10, headers=headers)
        if not payload:
            continue
        debug["endpoint"] = url
        debug["status"] = "RESPONSE_RECEIVED"

        # Current Underdog v6 shape: top-level over_under_lines + appearances + players.
        # This direct path is intentionally first so active MLB batter lines do not depend
        # on JSON:API-style relationships being present.
        if isinstance(payload, dict) and isinstance(payload.get("over_under_lines"), list):
            appearances = {str(a.get("id")): a for a in payload.get("appearances", []) if isinstance(a, dict)}
            players = {str(pl.get("id")): pl for pl in payload.get("players", []) if isinstance(pl, dict)}
            for line_obj in payload.get("over_under_lines", []):
                if not isinstance(line_obj, dict):
                    continue
                ou_obj = line_obj.get("over_under") if isinstance(line_obj.get("over_under"), dict) else {}
                app_stat = ou_obj.get("appearance_stat") if isinstance(ou_obj.get("appearance_stat"), dict) else {}
                app_obj = appearances.get(str(app_stat.get("appearance_id") or ""), {})
                player_obj = players.get(str(app_obj.get("player_id") or ""), {})
                option_blob = " | ".join(
                    str(opt.get(k, ""))
                    for opt in (line_obj.get("options") or []) if isinstance(opt, dict)
                    for k in ("selection_header", "selection_subheader", "status")
                )
                blob = " | ".join(x for x in [_ow_ud_blob(line_obj, ou_obj, app_stat, app_obj, player_obj), option_blob] if x)
                if len(debug["sample_market_text"]) < 12 and any(x in blob.lower() for x in ("hits", "rbi", "home run")):
                    debug["sample_market_text"].append(blob[:260])
                market = _ow_ud_market(blob)
                if market is None or not _ow_ud_active(line_obj):
                    continue
                if str(player_obj.get("sport_id") or "").upper() not in {"MLB", ""}:
                    continue
                line = _ow_ud_line_value(line_obj)
                if line is None:
                    continue
                if not _ow_ud_market_line_ok(market, line):
                    continue
                player = _ow_ud_player_name(player_obj) or _ow_ud_player_name(line_obj, ou_obj)
                if not player:
                    continue
                rows.append({
                    "Source": "Underdog",
                    "Player": player,
                    "Market": "HRR" if market == "HRR" else _ow_ud_market_label(market),
                    "Market Label": _ow_ud_market_label(market),
                    "Line": float(line),
                    "Evidence": blob[:350],
                    "Line ID": str(line_obj.get("id", "")),
                })

        objects = _ow_ud_collect(payload)
        debug["objects"] = len(objects)
        by_key, by_id = _ow_ud_object_maps(objects)
        candidates = []
        for obj in objects:
            attrs = _ow_ud_attrs(obj)
            typ = _ow_ud_type(obj)
            if "over_under_line" in typ or any(attrs.get(k) not in (None, "") for k in (
                "stat_value", "statValue", "line", "over_under_line", "overUnderLine",
                "target_value", "targetValue", "line_score", "lineScore", "display_stat_value",
            )):
                candidates.append(obj)
        debug["candidate_lines"] = len(candidates)

        for line_obj in candidates:
            ou_obj = _ow_ud_related(line_obj, ("over_under", "over_unders"), by_key, by_id)
            app_obj = _ow_ud_related(ou_obj, ("appearance", "appearances"), by_key, by_id) or _ow_ud_related(line_obj, ("appearance", "appearances"), by_key, by_id)
            player_obj = (
                _ow_ud_related(app_obj, ("player", "players"), by_key, by_id)
                or _ow_ud_related(ou_obj, ("player", "players"), by_key, by_id)
                or _ow_ud_related(line_obj, ("player", "players"), by_key, by_id)
            )
            blob = _ow_ud_blob(line_obj, ou_obj, app_obj, player_obj)
            if len(debug["sample_market_text"]) < 12 and any(x in blob.lower() for x in ("hits", "rbi", "home run")):
                debug["sample_market_text"].append(blob[:260])
            market = _ow_ud_market(blob)
            if market is None or not _ow_ud_active(line_obj, ou_obj, app_obj, player_obj):
                continue
            line = _ow_ud_line_value(line_obj, ou_obj, app_obj)
            if line is None:
                continue
            if not _ow_ud_market_line_ok(market, line):
                continue
            player = _ow_ud_player_name(player_obj, app_obj, ou_obj, line_obj)
            if not player:
                continue
            rows.append({
                "Source": "Underdog",
                "Player": player,
                "Market": "HRR" if market == "HRR" else _ow_ud_market_label(market),
                "Market Label": _ow_ud_market_label(market),
                "Line": float(line),
                "Evidence": blob[:350],
                "Line ID": str(line_obj.get("id", "")),
            })

        # Flattened fallback: useful when title, player, and line are all on one object.
        for obj in objects:
            blob = _ow_ud_blob(obj)
            market = _ow_ud_market(blob)
            if market is None or not _ow_ud_active(obj):
                continue
            line = _ow_ud_line_value(obj)
            if line is None:
                continue
            if not _ow_ud_market_line_ok(market, line):
                continue
            player = _ow_ud_player_name(obj)
            if not player:
                match = re.search(
                    r"([A-Z][A-Za-zÀ-ÿ.'’\-]+(?:\s+(?:[A-Z][A-Za-zÀ-ÿ.'’\-]+|Jr\.?|Sr\.?|II|III|IV)){1,5})"
                    r".{0,45}(?:Hits\s*\+\s*Runs\s*\+\s*RBIs?|H\s*\+\s*R\s*\+\s*R(?:BI)?|Home\s+Runs?)",
                    blob,
                    flags=re.I,
                )
                player = _ow_clean_ud_player(match.group(1)) if match else ""
            if player:
                rows.append({
                    "Source": "Underdog",
                    "Player": player,
                    "Market": "HRR" if market == "HRR" else _ow_ud_market_label(market),
                    "Market Label": _ow_ud_market_label(market),
                    "Line": float(line),
                    "Evidence": "flattened fallback: " + blob[:320],
                    "Line ID": str(obj.get("id", "")),
                })
        continue

    dedup = {}
    for row in rows:
        key = (_v3_norm_name(row.get("Player")), row.get("Market"), _v3_safe_num(row.get("Line"), None))
        if key not in dedup or row.get("Line ID"):
            dedup[key] = row
    out = list(dedup.values())
    debug["parsed_hrr"] = sum(1 for r in out if r.get("Market") == "HRR")
    debug["parsed_hr"] = sum(1 for r in out if r.get("Market") == "Home Runs")
    debug["status"] = "OK" if out else debug["status"]
    try:
        st.session_state["final_ud_batter_line_debug"] = debug
        st.session_state["hrr_ud_debug"] = debug
        st.session_state["hr_ud_debug"] = debug
    except Exception:
        pass
    return out, debug


@st.cache_data(ttl=120, show_spinner=False)
def fetch_underdog_batter_prop_rows():
    rows, debug = _ow_fetch_ud_batter_hrr_hr_lines()
    hrr = [r for r in rows if r.get("Market") == "HRR"]
    try:
        st.session_state["hrr_ud_debug"] = {**debug, "returned_hrr_rows": len(hrr)}
    except Exception:
        pass
    return hrr


def _v3_ud_hrr_rows():
    return fetch_underdog_batter_prop_rows() or []


def _v3_fetch_ud_home_run_rows():
    rows, debug = _ow_fetch_ud_batter_hrr_hr_lines()
    hr = [r for r in rows if r.get("Market") == "Home Runs"]
    try:
        st.session_state["hr_ud_debug"] = {**debug, "returned_hr_rows": len(hr)}
    except Exception:
        pass
    return hr




