def _ow_required_data_coverage_context(raw_line, logs, key_stats_ctx, lineup_ctx, team_ctx, pctx, bpctx, weather_ctx, protection_ctx, line_move_ctx, calibration_ctx, result_gate_ctx, projected_pa, savant_ctx=None, market="HRR"):
    checks = []
    missing = []
    try:
        log_cols = {"Date", "Batter", "Team", "Opponent", "Lineup Spot", "PA", "AB", "H", "R", "RBI", "TB", "BB", "K", "HR"}
        if logs and len(logs) >= 15:
            sample_keys = set()
            for g in logs[-5:]:
                sample_keys.update(str(k) for k in (g or {}).keys())
            if {"PA", "AB", "H", "R", "RBI", "HR"}.issubset(sample_keys) or len(logs) >= 30:
                checks.append("1 game logs")
            else:
                checks.append("1 game logs partial")
                missing.append("game log columns: " + ", ".join(sorted(log_cols - sample_keys)[:8]))
        else:
            missing.append("1 batter game logs")

        split_ok = _v3_safe_num((key_stats_ctx or {}).get("Split PA"), None) is not None and (
            _v3_safe_num((key_stats_ctx or {}).get("Split AVG"), None) is not None or
            _v3_safe_num((savant_ctx or {}).get("Savant xwOBA"), None) is not None
        )
        if split_ok:
            checks.append("2 splits vs hand")
        else:
            missing.append("2 splits vs hand")

        if (lineup_ctx or {}).get("Lineup Slot") is not None and (lineup_ctx or {}).get("Lineup Status"):
            checks.append("3 lineup/slot/status")
        else:
            missing.append("3 confirmed/projected lineup")

        if _v3_safe_num((team_ctx or {}).get("Team Runs"), None) is not None or _v3_safe_num((team_ctx or {}).get("Implied Runs"), None) is not None or str((line_move_ctx or {}).get("Sportsbook Market Status") or "").upper() in {"OK", "CONSENSUS", "ACTIVE", "LIVE"}:
            checks.append("4 implied/team runs")
        else:
            missing.append("4 implied runs/game total")

        pitcher_allowed_ok = any(_v3_safe_num((pctx or {}).get(k), None) is not None for k in ["Pitcher ERA", "Pitcher FIP", "Pitcher WHIP", "Pitcher H/9", "Pitcher HR9", "Pitcher K%", "Pitcher Allowed xwOBA", "Pitcher Allowed HardHit%", "Pitcher Allowed Barrel%"])
        if pitcher_allowed_ok:
            checks.append("5 pitcher allowed profile")
        else:
            missing.append("5 pitcher allowed profile")

        if (bpctx or {}).get("Bullpen Weakness Label") or _v3_safe_num((bpctx or {}).get("Bullpen Weakness Score"), None) is not None:
            checks.append("6 bullpen profile")
        else:
            missing.append("6 bullpen profile")

        if (weather_ctx or {}).get("Weather Temp F") is not None or "roof" in str((weather_ctx or {}).get("Weather Note") or "").lower() or "dome" in str((weather_ctx or {}).get("Weather Note") or "").lower():
            checks.append("7 park/weather")
        else:
            missing.append("7 park/weather")

        if _v3_safe_num((protection_ctx or {}).get("Ahead OBP"), None) is not None or _v3_safe_num((protection_ctx or {}).get("Behind SLG"), None) is not None:
            checks.append("8 lineup context")
        else:
            missing.append("8 lineup context around batter")

        if _v3_safe_num((calibration_ctx or {}).get("Projection Calibration Samples"), 0) or _v3_safe_num((result_gate_ctx or {}).get("Result Gate Samples"), 0):
            checks.append("9 historical calibration")
        else:
            missing.append("9 historical actuals/calibration")

        if _v3_safe_num(projected_pa, None) is not None and (lineup_ctx or {}).get("Lineup Slot") is not None:
            checks.append("10 PA projection")
        else:
            missing.append("10 PA projection")

        if _v3_safe_num((savant_ctx or {}).get("Savant xwOBA"), None) is not None:
            checks.append("Baseball Savant hitter")
        else:
            missing.append("Baseball Savant hitter leaderboard")

        score = int(round(clamp((len(checks) / 11.0) * 100, 0, 100)))
        return {
            "Required Data Score": score,
            "Required Data Loaded": " | ".join(checks) if checks else "—",
            "Required Data Missing": " | ".join(missing[:12]) if missing else "NONE",
            "Required Data Note": f"{score}/100 required projection inputs loaded",
        }
    except Exception as e:
        return {
            "Required Data Score": 50,
            "Required Data Loaded": "—",
            "Required Data Missing": "required data audit failed",
            "Required Data Note": f"required data audit failed: {e}",
        }


@st.cache_data(ttl=3600, show_spinner=False)
def _ow_batter_profile_csv_context(player):
    out = {
        "Profile CSV Found": "NO",
        "Profile CSV Source": "—",
        "Profile Factor HRR": 1.0,
        "Profile Factor HR": 1.0,
        "Profile hrr_pa": None,
        "Profile hr_pa": None,
        "Profile k_pa": None,
        "Profile BA": None,
        "Profile H": None,
        "Profile R": None,
        "Profile RBI": None,
        "Profile wRC+ Proxy": None,
        "Profile OPS": None,
        "Profile OPS+": None,
        "Profile PA": None,
        "Profile Note": "No local batter profile CSV match",
    }
    try:
        paths = [
            Path("/Users/j/Downloads/batter_profiles.csv"),
            Path("/Users/j/Documents/Codex/data/batter_profiles.csv"),
            Path("/Users/j/Documents/Codex/data/raw/batter_profiles.csv"),
            Path("/Users/j/Documents/Codex/data/raw/cleaned_batting_stats.csv"),
            Path("/Users/j/Downloads/cleaned_batting_stats.csv"),
            Path("data/batter_profiles.csv"),
            Path("data/raw/batter_profiles.csv"),
            Path("data/raw/cleaned_batting_stats.csv"),
        ]
        target = _v3_norm_name(player)
        best = None
        best_path = None
        for path in paths:
            try:
                if not path.exists():
                    continue
                df = pd.read_csv(path)
                if not isinstance(df, pd.DataFrame) or df.empty:
                    continue
                pcol = _v3_col(df, ["normalized_name", "player_name", "Name", "Player", "Batter", "full_name"])
                if not pcol:
                    continue
                d = df[df[pcol].map(_v3_norm_name) == target].copy()
                if d.empty and "normalized_name" in df.columns:
                    d = df[df["normalized_name"].astype(str).map(_v3_norm_name) == target].copy()
                if d.empty:
                    continue
                if "latest_year_pa" in d.columns:
                    d["_sort_pa"] = pd.to_numeric(d["latest_year_pa"], errors="coerce").fillna(0)
                    d = d.sort_values("_sort_pa", ascending=False)
                elif "PA" in d.columns:
                    d["_sort_pa"] = pd.to_numeric(d["PA"], errors="coerce").fillna(0)
                    d = d.sort_values("_sort_pa", ascending=False)
                best = d.iloc[0].to_dict()
                best_path = path
                break
            except Exception:
                continue
        if not best:
            return out

        hrr_pa = _v3_safe_num(best.get("hrr_pa"), None)
        hr_pa = _v3_safe_num(best.get("hr_pa"), None)
        k_pa = _v3_safe_num(best.get("k_pa"), None)
        ba = _v3_safe_num(best.get("ba") or best.get("BA"), None)
        profile_h = _v3_safe_num(best.get("career_h") or best.get("H") or best.get("hits"), None)
        profile_r = _v3_safe_num(best.get("career_r") or best.get("R") or best.get("runs"), None)
        profile_rbi = _v3_safe_num(best.get("career_rbi") or best.get("RBI") or best.get("rbi"), None)
        ops = _v3_safe_num(best.get("ops") or best.get("OPS"), None)
        ops_plus = _v3_safe_num(best.get("ops_plus") or best.get("OPS+"), None)
        wrc_proxy = _v3_safe_num(
            best.get("wRC+") or best.get("wrc_plus") or best.get("wrc_plus_proxy") or
            best.get("ops_plus") or best.get("OPS+") or best.get("rbat_plus") or best.get("Rbat+"),
            None,
        )
        profile_pa = _v3_safe_num(best.get("effective_pa") or best.get("career_pa") or best.get("latest_year_pa") or best.get("PA"), None)
        hrr_trend = _v3_safe_num(best.get("hrr_pa_trend"), None)
        latest_hrr = _v3_safe_num(best.get("latest_year_hrr_pa"), None)

        hrr_factor = 1.0
        hr_factor = 1.0
        notes = []
        if profile_pa is not None and profile_pa < 75:
            notes.append(f"profile small PA {profile_pa:.0f}")
        if hrr_pa is not None:
            if hrr_pa >= 0.54:
                hrr_factor *= 1.040
                notes.append(f"profile HRR/PA strong {hrr_pa:.3f}")
            elif hrr_pa <= 0.34:
                hrr_factor *= 0.955
                notes.append(f"profile HRR/PA light {hrr_pa:.3f}")
        if latest_hrr is not None and hrr_pa is not None and profile_pa and profile_pa >= 100:
            diff = latest_hrr - hrr_pa
            if diff >= 0.055:
                hrr_factor *= 1.018
                notes.append(f"latest HRR trend up {diff:+.3f}")
            elif diff <= -0.055:
                hrr_factor *= 0.982
                notes.append(f"latest HRR trend down {diff:+.3f}")
        if hrr_trend is not None:
            if hrr_trend >= 0.030:
                hrr_factor *= 1.012
            elif hrr_trend <= -0.030:
                hrr_factor *= 0.988
        if hr_pa is not None:
            if hr_pa >= 0.045:
                hr_factor *= 1.070
                notes.append(f"profile HR/PA power {hr_pa:.3f}")
            elif hr_pa <= 0.018:
                hr_factor *= 0.930
                notes.append(f"profile HR/PA low {hr_pa:.3f}")
        if ops is not None:
            if ops >= 0.820:
                hrr_factor *= 1.020
                hr_factor *= 1.025
                notes.append(f"profile OPS {ops:.3f}")
            elif ops <= 0.650:
                hrr_factor *= 0.975
                hr_factor *= 0.965
                notes.append(f"profile OPS low {ops:.3f}")
        if ops_plus is not None:
            if ops_plus >= 120:
                hrr_factor *= 1.015
                hr_factor *= 1.020
            elif ops_plus <= 85:
                hrr_factor *= 0.985
                hr_factor *= 0.980
        if k_pa is not None:
            if k_pa >= 0.285:
                hrr_factor *= 0.975
                hr_factor *= 0.990
                notes.append(f"profile K/PA risk {k_pa:.3f}")
            elif k_pa <= 0.165:
                hrr_factor *= 1.018
                notes.append(f"profile contact K/PA {k_pa:.3f}")
        out.update({
            "Profile CSV Found": "YES",
            "Profile CSV Source": str(best_path),
            "Profile Factor HRR": round(float(clamp(hrr_factor, 0.92, 1.08)), 3),
            "Profile Factor HR": round(float(clamp(hr_factor, 0.88, 1.12)), 3),
            "Profile hrr_pa": None if hrr_pa is None else round(hrr_pa, 3),
            "Profile hr_pa": None if hr_pa is None else round(hr_pa, 3),
            "Profile k_pa": None if k_pa is None else round(k_pa, 3),
            "Profile BA": None if ba is None else round(ba, 3),
            "Profile H": None if profile_h is None else round(profile_h, 1),
            "Profile R": None if profile_r is None else round(profile_r, 1),
            "Profile RBI": None if profile_rbi is None else round(profile_rbi, 1),
            "Profile wRC+ Proxy": None if wrc_proxy is None else round(wrc_proxy, 1),
            "Profile OPS": None if ops is None else round(ops, 3),
            "Profile OPS+": None if ops_plus is None else round(ops_plus, 1),
            "Profile PA": None if profile_pa is None else round(profile_pa, 1),
            "Profile Note": ", ".join(notes) if notes else "Profile CSV neutral",
        })
        return out
    except Exception:
        return out


def _ow_pitcher_matchup_factors(team):
    team_abbr = _ow_team_abbr(team)
    pctx = _v3_pitcher_weakness_summary(team_abbr)
    direct = _ow_probable_pitcher_context(team_abbr)
    for key, value in direct.items():
        if value not in (None, "", "—"):
            pctx[key] = value
    stuff = _ow_pitcher_stuff_context(pctx.get("Pitcher ID"))
    pctx.update(stuff)
    recent_ctx = _ow_local_pitcher_recent_log_context(pctx.get("Opp Pitcher"))
    for key, value in recent_ctx.items():
        if value not in (None, "", "—", "MISSING"):
            pctx[key] = value
    grade_ctx = _ow_local_pitcher_graded_history_context(pctx.get("Opp Pitcher"))
    for key, value in grade_ctx.items():
        if value not in (None, "", "—", "MISSING"):
            pctx[key] = value
    hr9 = _v3_safe_num(pctx.get("Pitcher HR9"), None)
    kp = _v3_safe_num(pctx.get("Pitcher K%"), None)
    era = _v3_safe_num(pctx.get("Pitcher ERA"), None)
    whip = _v3_safe_num(pctx.get("Pitcher WHIP"), None)
    baa = _v3_safe_num(pctx.get("Pitcher BAA"), None)
    h9 = _v3_safe_num(pctx.get("Pitcher H/9"), None)
    bb9 = _v3_safe_num(pctx.get("Pitcher BB/9"), None)
    fip = _v3_safe_num(pctx.get("Pitcher FIP"), None)
    allowed_xwoba = _v3_safe_num(pctx.get("Pitcher Allowed xwOBA"), None)
    allowed_xslg = _v3_safe_num(pctx.get("Pitcher Allowed xSLG"), None)
    allowed_hardhit = _v3_safe_num(pctx.get("Pitcher Allowed HardHit%"), None)
    allowed_barrel = _v3_safe_num(pctx.get("Pitcher Allowed Barrel%"), None)
    hr_factor = 1.0
    hrr_factor = 1.0
    contact_factor = 1.0
    notes = []
    if hr9 is not None:
        if hr9 >= 1.60:
            hr_factor *= 1.18
            hrr_factor *= 1.04
            notes.append(f"HR9 friendly {hr9:.2f}")
        elif hr9 >= 1.25:
            hr_factor *= 1.09
            hrr_factor *= 1.02
            notes.append(f"HR9 elevated {hr9:.2f}")
        elif hr9 <= 0.65:
            hr_factor *= 0.88
            hrr_factor *= 0.98
            notes.append(f"HR9 suppressor {hr9:.2f}")
    if kp is not None:
        if kp <= 18:
            hrr_factor *= 1.04
            hr_factor *= 1.03
            notes.append(f"low K% {kp:.1f}")
        elif kp >= 27:
            hrr_factor *= 0.96
            hr_factor *= 0.97
            notes.append(f"high K% {kp:.1f}")
    if era is not None:
        if era >= 5.00:
            hrr_factor *= 1.035
            hr_factor *= 1.025
            contact_factor *= 1.030
            notes.append(f"ERA attack {era:.2f}")
        elif era <= 3.25:
            hrr_factor *= 0.985
            hr_factor *= 0.990
            contact_factor *= 0.985
            notes.append(f"ERA suppressor {era:.2f}")
    if whip is not None:
        if whip >= 1.38:
            hrr_factor *= 1.040
            contact_factor *= 1.045
            notes.append(f"WHIP traffic {whip:.2f}")
        elif whip <= 1.08:
            hrr_factor *= 0.975
            hr_factor *= 0.985
            contact_factor *= 0.975
            notes.append(f"low WHIP {whip:.2f}")
    if baa is not None:
        if baa >= 0.270:
            hrr_factor *= 1.030
            contact_factor *= 1.040
            notes.append(f"BAA friendly {baa:.3f}")
        elif baa <= 0.215:
            hrr_factor *= 0.975
            contact_factor *= 0.970
            notes.append(f"BAA suppressor {baa:.3f}")
    if h9 is not None:
        if h9 >= 9.3:
            hrr_factor *= 1.020
            contact_factor *= 1.025
            notes.append(f"H/9 elevated {h9:.1f}")
        elif h9 <= 7.1:
            hrr_factor *= 0.985
            contact_factor *= 0.985
            notes.append(f"H/9 low {h9:.1f}")
    if bb9 is not None:
        if bb9 >= 3.7:
            hrr_factor *= 1.012
            notes.append(f"walk traffic BB/9 {bb9:.1f}")
        elif bb9 <= 1.8:
            hrr_factor *= 0.992
    if fip is not None and era is not None:
        if fip >= era + 0.65:
            hrr_factor *= 1.010
            hr_factor *= 1.010
            notes.append(f"FIP warning {fip:.2f}")
        elif fip <= era - 0.65:
            hrr_factor *= 0.990
            hr_factor *= 0.990
            notes.append(f"ERA may regress down by FIP {fip:.2f}")
    if allowed_xwoba is not None:
        if allowed_xwoba >= 0.365:
            hrr_factor *= 1.025
            hr_factor *= 1.040
            contact_factor *= 1.025
            notes.append(f"Savant allowed xwOBA attack {allowed_xwoba:.3f}")
        elif allowed_xwoba <= 0.295:
            hrr_factor *= 0.985
            hr_factor *= 0.975
            contact_factor *= 0.985
            notes.append(f"Savant allowed xwOBA suppressor {allowed_xwoba:.3f}")
    if allowed_xslg is not None:
        if allowed_xslg >= 0.470:
            hr_factor *= 1.040
            notes.append(f"Savant allowed xSLG power {allowed_xslg:.3f}")
        elif allowed_xslg <= 0.350:
            hr_factor *= 0.978
    if allowed_hardhit is not None:
        if allowed_hardhit >= 45:
            hrr_factor *= 1.010
            hr_factor *= 1.030
            notes.append(f"Savant hard-hit allowed {allowed_hardhit:.1f}%")
        elif allowed_hardhit <= 34:
            hr_factor *= 0.982
    if allowed_barrel is not None:
        if allowed_barrel >= 9:
            hr_factor *= 1.050
            notes.append(f"Savant barrel allowed {allowed_barrel:.1f}%")
        elif allowed_barrel <= 5:
            hr_factor *= 0.970
    stuff_hrr = _v3_safe_num(pctx.get("Pitcher Stuff Factor HRR"), 1.0) or 1.0
    stuff_hr = _v3_safe_num(pctx.get("Pitcher Stuff Factor HR"), 1.0) or 1.0
    hrr_factor *= stuff_hrr
    hr_factor *= stuff_hr
    stuff_note = str(pctx.get("Pitcher Stuff Note") or "")
    if stuff_note and stuff_note != "Statcast pitcher stuff unavailable":
        notes.append(stuff_note)
    pctx["HR Matchup Factor"] = round(float(clamp(hr_factor, 0.84, 1.22)), 3)
    pctx["HRR Matchup Factor"] = round(float(clamp(hrr_factor, 0.92, 1.08)), 3)
    pctx["Pitcher Contact Factor"] = round(float(clamp(contact_factor, 0.94, 1.07)), 3)
    pctx["Pitcher Matchup Note"] = ", ".join(notes) if notes else "Pitcher matchup neutral"
    return pctx


def _ow_blowout_game_environment_context(team_runs, pctx, bpctx=None, lineup_ctx=None, market="HRR"):
    """High-run/bad-pitcher environment signal with a small late-rest guardrail."""
    out = {
        "Blowout Environment Factor HRR": 1.0,
        "Blowout Environment Factor HR": 1.0,
        "Blowout Run Score": 50,
        "Blowout Stack Signal": "NEUTRAL",
        "Blowout Risk Label": "NEUTRAL",
        "Blowout Note": "Neutral run environment",
    }
    try:
        tr = _v3_safe_num(team_runs, None)
        era = _v3_safe_num((pctx or {}).get("Pitcher ERA"), None)
        whip = _v3_safe_num((pctx or {}).get("Pitcher WHIP"), None)
        baa = _v3_safe_num((pctx or {}).get("Pitcher BAA"), None)
        h9 = _v3_safe_num((pctx or {}).get("Pitcher H/9"), None)
        bb9 = _v3_safe_num((pctx or {}).get("Pitcher BB/9"), None)
        hr9 = _v3_safe_num((pctx or {}).get("Pitcher HR9"), None)
        kp = _v3_safe_num((pctx or {}).get("Pitcher K%"), None)
        allowed_xwoba = _v3_safe_num((pctx or {}).get("Pitcher Allowed xwOBA"), None)
        allowed_hardhit = _v3_safe_num((pctx or {}).get("Pitcher Allowed HardHit%"), None)
        allowed_barrel = _v3_safe_num((pctx or {}).get("Pitcher Allowed Barrel%"), None)
        bp_score = _v3_safe_num((bpctx or {}).get("Bullpen Weakness Score"), 50) or 50
        slot = _v3_safe_num((lineup_ctx or {}).get("Lineup Slot"), None)
        score = 50.0
        notes = []
        if tr is not None:
            if tr >= 5.4:
                score += 18
                notes.append(f"team total smash {tr:.2f}")
            elif tr >= 5.0:
                score += 12
                notes.append(f"high team total {tr:.2f}")
            elif tr >= 4.6:
                score += 6
                notes.append(f"above-average team total {tr:.2f}")
            elif tr <= 3.6:
                score -= 14
                notes.append(f"low team total {tr:.2f}")
        if era is not None:
            if era >= 5.00:
                score += 9
                notes.append(f"attack ERA {era:.2f}")
            elif era <= 3.20:
                score -= 6
        if whip is not None:
            if whip >= 1.38:
                score += 8
                notes.append(f"traffic WHIP {whip:.2f}")
            elif whip <= 1.08:
                score -= 6
        if baa is not None:
            if baa >= 0.270:
                score += 7
                notes.append(f"hits allowed BAA {baa:.3f}")
            elif baa <= 0.215:
                score -= 6
        if h9 is not None and h9 >= 9.3:
            score += 6
            notes.append(f"H/9 {h9:.1f}")
        if bb9 is not None and bb9 >= 3.7:
            score += 4
            notes.append(f"BB traffic {bb9:.1f}/9")
        if hr9 is not None:
            if hr9 >= 1.45:
                score += 6
                notes.append(f"HR prone {hr9:.2f}/9")
            elif hr9 <= 0.70:
                score -= 4
        if kp is not None:
            if kp <= 18:
                score += 6
                notes.append(f"low K pitcher {kp:.1f}%")
            elif kp >= 27:
                score -= 7
        if allowed_xwoba is not None and allowed_xwoba >= 0.365:
            score += 7
            notes.append(f"xwOBA allowed {allowed_xwoba:.3f}")
        if allowed_hardhit is not None and allowed_hardhit >= 45:
            score += 4
        if allowed_barrel is not None and allowed_barrel >= 9:
            score += 4
        if bp_score >= 62:
            score += 7
            notes.append("weak bullpen behind starter")
        elif bp_score <= 42:
            score -= 4
        score = float(clamp(score, 0, 100))
        hrr_factor = 1.0
        hr_factor = 1.0
        if score >= 82:
            hrr_factor = 1.065
            hr_factor = 1.030
            label = "BLOWOUT STACK"
        elif score >= 70:
            hrr_factor = 1.045
            hr_factor = 1.020
            label = "STACK FRIENDLY"
        elif score >= 60:
            hrr_factor = 1.020
            hr_factor = 1.010
            label = "RUN FRIENDLY"
        elif score <= 38:
            hrr_factor = 0.970
            hr_factor = 0.985
            label = "RUN SUPPRESSED"
        else:
            label = "NEUTRAL"
        rest_risk = bool(score >= 82 and slot is not None and slot >= 6)
        if rest_risk:
            hrr_factor *= 0.985
            hr_factor *= 0.995
            risk = "BLOWOUT UPSIDE / LATE REST RISK"
            notes.append("late pinch-hit/rest risk for lower lineup slot")
        else:
            risk = label
        if slot is not None and slot <= 5 and score >= 70:
            hrr_factor *= 1.010
        out.update({
            "Blowout Environment Factor HRR": round(float(clamp(hrr_factor, 0.95, 1.075)), 3),
            "Blowout Environment Factor HR": round(float(clamp(hr_factor, 0.975, 1.040)), 3),
            "Blowout Run Score": int(round(score)),
            "Blowout Stack Signal": label,
            "Blowout Risk Label": risk,
            "Blowout Note": ", ".join(notes[:6]) if notes else "Neutral run environment",
        })
    except Exception:
        pass
    return out


